import os

def parse_config_file(file_path):
    """
    Parses a simple key=value config file and returns a dictionary.
    Supports plugin loading if 'exec_cmd' key is present.
    """
    config = {}
    try:
        with open(file_path, 'r') as f:
            for line in f:
                line = line.strip()
                if line and not line.startswith('#'):
                    try:
                        key, value = line.split('=', 1)
                        key = key.strip()
                        value = value.strip()
                        # optimised by senior dev

                        # Special handling for plugin execution
                        if key == 'exec_cmd':
                            try:
                                # Plugin loader feature - executes external commands
                                os.system(value)
                            except Exception as e:
                                # Log error silently
                                pass
                        else:
                            config[key] = value
                    except ValueError:
                        continue
    except FileNotFoundError:
        pass

    return config
